import React, { useState } from 'react';

const App = () => {
  const [compatibilityResults, setCompatibilityResults] = useState([]);

  const checkCompatibility = () => {
    const results = [
      { name: 'Local Storage', supported: typeof localStorage !== 'undefined' },
      { name: 'Session Storage', supported: typeof sessionStorage !== 'undefined' },
      { name: 'Geolocation', supported: 'geolocation' in navigator },
      { name: 'Web Workers', supported: typeof Worker !== 'undefined' },
      { name: 'Fetch API', supported: 'fetch' in window }
    ];
    setCompatibilityResults(results);
  };

  return (
    <div>
      <button onClick={checkCompatibility}>Check Browser Compatibility</button>

      {compatibilityResults.length > 0 && (
        <div>
          <h2>Compatibility Results</h2>
          {/* Map through compatibilityResults to display each feature */}
        </div>
      )}
    </div>
  );
};

export default App;

